import { fileURLToPath } from 'node:url';
// Expected values are specified independently, never generated by the parsers under test.
const C='e5000000-0000-4000-8000-000000000001',S='f5000000-0000-4000-8000-000000000001';
const base={
 customer:{customer_type:'person',display_name:'  Ada  '},
 site:{customer_id:C,name:'  Home  '},
 metering_point:{site_id:S,external_metering_point_id:'735999000000000001'},
 asset:{customer_id:C,site_id:S,asset_type:'ev',display_name:'  Car  '},
};
const expected={
 customer:{customer_type:'person',display_name:'Ada',external_customer_id:null},
 site:{customer_id:C,name:'Home',external_site_id:null,country_code:'SE',timezone:'Europe/Stockholm'},
 metering_point:{site_id:S,external_metering_point_id:'735999000000000001',metering_point_type:'consumption',measurement_resolution_minutes:15,market_area_id:null},
 asset:{customer_id:C,site_id:S,asset_type:'ev',display_name:'Car',external_id:null,manufacturer:null,model:null,rated_power_kw:null,energy_capacity_kwh:null},
};
export const cases=[];
function good(kind,name,change={},result={}){cases.push({kind,name,input:{...base[kind],...change},expected:{...expected[kind],...result}});}
function bad(kind,name,change){cases.push({kind,name,input:{...base[kind],...change},error:'VALIDATION_ERROR'});}
for(const kind of Object.keys(base)){
 good(kind,`${kind} defaults`);bad(kind,`${kind} ownership injection`,{tenant_id:C});
 for(const input of [null,[]]) cases.push({kind,name:`${kind} non-object ${JSON.stringify(input)}`,input,error:'VALIDATION_ERROR'});
}
good('customer','Unicode whitespace',{display_name:'\u00a0أدا\u2003'},{display_name:'أدا'});
good('customer','Unicode scalar boundary',{display_name:'🚗'.repeat(200)},{display_name:'🚗'.repeat(200)});
good('customer','company external ID',{customer_type:'company',external_customer_id:'  company-1  '},{customer_type:'company',external_customer_id:'company-1'});
for(const v of ['viewer','person ',null,true,5])bad('customer',`invalid customer type ${v}`,{customer_type:v});
for(const v of ['', '  ', 'a\n', 'a\x7f', 'x'.repeat(201),'🚗'.repeat(201),null,42])bad('customer',`invalid name ${JSON.stringify(v).slice(0,40)}`,{display_name:v});
for(const v of ['',0,false,{}])bad('customer',`invalid external identifier ${JSON.stringify(v)}`,{external_customer_id:v});
good('site','explicit UTC',{country_code:'NO',timezone:'UTC',external_site_id:'site-1'},{country_code:'NO',timezone:'UTC',external_site_id:'site-1'});
for(const v of [null,'se','SE\n','SWE',5])bad('site',`invalid country ${JSON.stringify(v)}`,{country_code:v});
for(const v of [null,'Mars/Olympus','',42])bad('site',`invalid timezone ${JSON.stringify(v)}`,{timezone:v});
for(const v of [null,C+'\n','invalid',C.replace('8000','0000')])bad('site',`invalid customer UUID ${JSON.stringify(v)}`,{customer_id:v});
good('metering_point','production meter',{metering_point_type:'production',measurement_resolution_minutes:60},{metering_point_type:'production',measurement_resolution_minutes:60});
for(const v of [0,-1,1.5,1441,'15',null,false])bad('metering_point',`invalid resolution ${JSON.stringify(v)}`,{measurement_resolution_minutes:v});
for(const v of [null,'other',1])bad('metering_point',`invalid meter type ${JSON.stringify(v)}`,{metering_point_type:v});
good('asset','exact decimal normalization',{rated_power_kw:'11.000',energy_capacity_kwh:'80.500'},{rated_power_kw:'11',energy_capacity_kwh:'80.5'});
good('asset','UUID case normalization',{customer_id:C.toUpperCase(),site_id:S.toUpperCase()},{customer_id:C,site_id:S});
for(const v of ['1\n','01','1.0001','1e3','NaN','Infinity','-1','1000000000',11,true,' 1'])bad('asset',`invalid rated power ${JSON.stringify(v)}`,{rated_power_kw:v});
for(const v of ['100000000000','1.0001',80])bad('asset',`invalid capacity ${JSON.stringify(v)}`,{energy_capacity_kwh:v});
for(const v of ['vehicle','ev_charger',null,3])bad('asset',`provider spelling ${JSON.stringify(v)}`,{asset_type:v});
bad('asset','cannot enable physical control at registration',{controllable:true});
if(process.argv[1]===fileURLToPath(import.meta.url))console.log(JSON.stringify(cases));
